  "expiresAt": $expires.ts_format("2006-01-02T15:04:05Z", "UTC").catch(null)
}.filter(kv -> kv.value != null)

let now = now().ts_unix()
let times = this.features.or([]).map_each(f -> f.attributes.newest.or("").string().ts_parse("2006-01-02T15:04:05Z07:00").ts_unix().catch(null)).filter(t -> t != null && t <= $now + 86400)
