let to = (($next + "T00:00:00") + ($next + "T00:00:00Z").ts_parse("2006-01-02T15:04:05Z07:00").ts_format("-07:00", "Europe/Bratislava")).ts_parse("2006-01-02T15:04:05Z07:00")
# A throw here would keep the newest rows as the message: the problem rides on it instead and
# fails the run at the end, after nothing was read or written.
root = { "day": $day, "from": $from.ts_format("2006-01-02T15:04:05Z", "UTC"), "to": $to.ts_format("2006-01-02T15:04:05Z", "UTC"),
  "problem": if $times.length() == 0 { "the counters answered no row time" } else if $to.ts_unix() < $now - 259200 { "the newest day the counters closed, %v, is more than three days old".format($day) } else { null } }
meta from = $from.ts_format("2006-01-02T15:04:05", "UTC")
meta to = $to.ts_format("2006-01-02T15:04:05", "UTC")

let box = { "w": 16.93, "s": 47.99, "e": 17.3, "n": 48.28 }
let modes = [
  { "mode": "cycle", "rows": this.cycle.rows.or([]), "cap": 5000, "vehicleType": "bicycle", "provider": "cyklisti2_0" },
  { "mode": "vehicle", "rows": this.vehicle.rows.or([]), "cap": 10000, "vehicleType": null, "provider": "vozidla_00" }
]
let day = this
let judged = $modes.map_each(m -> m.rows.map_each(r -> {
  "mode": m.mode, "cap": m.cap, "vehicleType": m.vehicleType, "provider": m.provider,
  "name": r.NAZOV.or("").string().trim(),
  "key": r.NAZOV.or("").string().trim().re_find_all_submatch("^#([0-9]+) ").index(0).index(1).catch(r.NAZOV.or("").string().lowercase().re_replace_all("[^a-z0-9]+", "-").trim("-")),
  "lat": r.ZEMEPISNA_SIRKA.or(null), "lon": r.ZEMEPISNA_DLZKA.or(null),
  "towardsLabel": r.SMER_DO.or("").string().trim(), "awayLabel": r.SMER_Z.or("").string().trim().re_replace_all("^NIE JE.*", "protismer"),
  "towards": r.towards.or(null), "away": r.away.or(null), "towardsMin": r.towardsMin.or(null), "towardsMax": r.towardsMax.or(null),
  "awayMin": r.awayMin.or(null), "awayMax": r.awayMax.or(null), "rows": r.rows.or(0)
}).enumerated().map_each(e -> e.value.assign({ "reason":
  if e.value.key == "" { "noName" }
  else if e.value.lon.type() != "number" || e.value.lat.type() != "number" { "noLocation" }
  else if !(e.value.lon >= $box.w && e.value.lon <= $box.e && e.value.lat >= $box.s && e.value.lat <= $box.n) {
    if e.value.lat >= $box.w && e.value.lat <= $box.e && e.value.lon >= $box.s && e.value.lon <= $box.n { "swappedCoordinates" } else { "outsideBratislava" }
  }
  else { null }
}))).flatten()
let valid = $judged.filter(s -> s.reason == null)
let groups = $valid.enumerated().filter(e -> !$valid.slice(0, e.index).any(o -> o.mode == e.value.mode && o.key == e.value.key)).map_each(e -> e.value.assign({
  "twins": $valid.filter(o -> o.mode == e.value.mode && o.key == e.value.key).slice(1) })).map_each(s -> s.assign({ "hours": s.twins.fold(s.rows, t -> t.tally + t.value.rows) }))
let merged = $groups.map_each(s -> if s.twins.length() == 0 || s.hours > 25 { s } else { s.assign({
  "towards": s.twins.fold(s.towards, t -> t.tally + t.value.towards), "away": s.twins.fold(s.away, t -> t.tally + t.value.away),
  "towardsMin": s.twins.fold(s.towardsMin, t -> [t.tally, t.value.towardsMin].min()), "towardsMax": s.twins.fold(s.towardsMax, t -> [t.tally, t.value.towardsMax].max()),
  "awayMin": s.twins.fold(s.awayMin, t -> [t.tally, t.value.awayMin].min()), "awayMax": s.twins.fold(s.awayMax, t -> [t.tally, t.value.awayMax].max()) }) })
let duplicates = $groups.filter(s -> s.hours > 25).map_each(s -> s.twins).flatten().map_each(t -> t.assign({ "reason": "duplicate" }))
# A site without the mode's sensor writes 0 every hour (14 of the 19 vehicle sites and three
# pedestrian ones counted nothing from 2026-09-21 to 2026-10-21): a day of 0 both ways is no count.
let silent = $merged.filter(s -> s.towards.or(0) + s.away.or(0) == 0).map_each(s -> s.assign({ "reason": "zeroDay" }))
let directions = $merged.filter(s -> s.towards.or(0) + s.away.or(0) != 0).map_each(s -> [
  s.assign({ "direction": "forward", "label": s.towardsLabel, "count": s.towards, "min": s.towardsMin, "max": s.towardsMax }),
  s.assign({ "direction": "backward", "label": s.awayLabel, "count": s.away, "min": s.awayMin, "max": s.awayMax })
]).flatten().map_each(d -> d.assign({ "reason":
  if d.count.type() != "number" || d.min.type() != "number" || d.max.type() != "number" || d.min < 0 || d.max > d.cap { "outOfRange" } else { null } }))
let dropped = $judged.filter(s -> s.reason != null).concat($duplicates, $silent, $directions.filter(d -> d.reason != null)).fold({}, t -> t.tally.assign({ t.value.mode + ":" + t.value.reason: t.tally.get(t.value.mode + ":" + t.value.reason).or(0) + 1 }))
meta dropped = if $dropped.keys().length() > 0 { $dropped.format_json(no_indent: true) } else { "" }
root = $directions.filter(d -> d.reason == null).map_each(d -> {
  "id": "urn:ngsi-ld:%v:%v:%v:%v-%v-%v".format("TrafficFlowObserved", env("JC_ORG_DOMAIN"), "bratislava", d.mode, d.key, d.direction),
  "type": "TrafficFlowObserved",
  "name": { "type": "Property", "value": "%v (%v)".format(d.name, d.label) },
  "location": { "type": "GeoProperty", "value": { "type": "Point", "coordinates": [d.lon, d.lat] } },
  "dateObserved": { "type": "Property", "value": $day.to },
  "dateObservedFrom": { "type": "Property", "value": $day.from },
  "dateObservedTo": { "type": "Property", "value": $day.to },
  "intensity": { "type": "Property", "value": d.count.round(), "observedAt": $day.to },
  "vehicleType": if d.vehicleType == null { null } else { { "type": "Property", "value": d.vehicleType } },
  "laneDirection": { "type": "Property", "value": d.direction },
  "dataProvider": { "type": "Property", "value": "Hlavné mesto SR Bratislava, data.bratislava.sk (CC BY 4.0)" },
  "source": { "type": "Property", "value": "https://services8.arcgis.com/pRlN1m0su5BYaFAS/arcgis/rest/services/%v/FeatureServer/0".format(d.provider) }
}.filter(entry -> entry.value != null))
